// Mock content layer for `changelogEntry` (plan §8.3). Human-friendly release
// notes — the per-package CHANGELOG.md files generated by Changesets remain the
// machine-readable source of truth.
import { block, bullet, type PortableTextNode } from "./portable-text";

export interface ChangelogEntry {
  version: string;
  date: string;
  title: string;
  body: PortableTextNode[];
}

const entries: ChangelogEntry[] = [
  {
    version: "0.1.0-dev",
    date: "2026-11-18",
    title: "First three effects and the runtime",
    body: [
      block(
        "The core runtime and the first three background effects are in place. Nothing is published to npm yet — this entry tracks development progress.",
      ),
      bullet("aurora — soft flowing northern-lights bands."),
      bullet("mesh-gradient — slowly morphing multi-point colour mesh."),
      bullet("grain-gradient — animated angled gradient with film grain."),
      block(
        "The runtime handles resize and device pixel ratio, pausing offscreen and in hidden tabs, reduced-motion fallbacks, WebGL context loss, and a shared animation loop across every effect on a page.",
      ),
    ],
  },
];

export function getChangelogEntries(): ChangelogEntry[] {
  return [...entries].sort((a, b) => b.date.localeCompare(a.date));
}
